use vstd::prelude::*;

verus! {
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            0 < n < list.len(),
        ensures
            new_list.len() == list.len(),
            forall(|i: usize| 0 <= i < new_list.len() ==> new_list[i] == if i < list.len() - n { list[i + n] } else { list[i - (list.len() - n)] }),
    {
        let len = list.len();
        let mut new_list: Vec<i32> = Vec::with_capacity(len);
        
        // Append elements from index n to the end of the original list
        for i in n..len {
            new_list.push(list[i]);
        }
        
        // Append elements from index 0 to n-1 of the original list
        for i in 0..n {
            new_list.push(list[i]);
        }
        
        new_list
    }
}
